html:
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value or 0, currency=doc.currency) }}{%- endmacro -%}
{%- set earnings = doc.earnings | rejectattr("do_not_include_in_total") | selectattr("amount") | list -%}
{%- set deductions = doc.deductions | rejectattr("do_not_include_in_total") | selectattr("amount") | list -%}
{%- set disable_rounded_total = frappe.db.get_single_value("Payroll Settings", "disable_rounded_total") -%}
{%- set net_total = doc.net_pay if disable_rounded_total else (doc.rounded_total or doc.net_pay) -%}

<style>
	.ss-doc {
		font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
		color: #1a1a1a;
		font-size: 12px;
		line-height: 1.45;
	}
	.ss-doc table { border-collapse: collapse; width: 100%; }
	.ss-doc td, .ss-doc th { vertical-align: top; padding: 0; }
	.ss-doc .letter-head { margin-bottom: 12px; }
	.ss-num { font-variant-numeric: tabular-nums; white-space: nowrap; }
	.ss-right { text-align: right; }
	.ss-label {
		font-size: 9.5px;
		letter-spacing: 0.1em;
		text-transform: uppercase;
		color: #757575;
		font-weight: bold;
	}
	.ss-head-rule { border-top: 2px solid #1a1a1a; margin-bottom: 16px; }

	.ss-who td { padding-bottom: 16px; }
	.ss-who .name { font-size: 15px; font-weight: bold; letter-spacing: -0.01em; }
	.ss-who .sub { font-size: 10.5px; color: #757575; margin-top: 1px; }
	.ss-who .period { font-size: 11.5px; font-weight: bold; margin-top: 1px; }

	.ss-hero { background-color: #f2f2f2; }
	.ss-hero td { padding: 16px 18px; }
	.ss-hero .amt {
		font-size: 30px;
		font-weight: bold;
		line-height: 1.15;
		letter-spacing: -0.02em;
		white-space: nowrap;
		margin-top: 1px;
	}
	.ss-hero .words { font-size: 10.5px; color: #757575; margin-top: 4px; }
	.ss-hero .pay {
		text-align: right;
		font-size: 10.5px;
		color: #444444;
		line-height: 1.65;
		white-space: nowrap;
	}
	.ss-hero .pay .ss-label { margin-bottom: 2px; }

	.ss-ledger { margin-top: 22px; }
	.ss-ledger col.amt { width: 30%; }
	.ss-ledger td {
		padding: 6px 0;
		border-bottom: 1px solid #e2e2e2;
		font-size: 11.5px;
		text-align: right;
		color: #444444;
	}
	.ss-ledger td.c { text-align: left; }
	.ss-ledger tr.ss-sec td {
		border-bottom: 1px solid #b0b0b0;
		border-top: 1px solid #b0b0b0;
		padding: 6px 0 5px;
		font-size: 9.5px;
		letter-spacing: 0.1em;
		text-transform: uppercase;
		color: #757575;
		font-weight: bold;
	}
	.ss-ledger tr.ss-sec.first td { border-top: none; padding-top: 0; }
	.ss-ledger tr.ss-sec td.c { text-align: left; }
	.ss-ledger tr.ss-sub td {
		border-bottom: none;
		border-top: 1px solid #b0b0b0;
		padding-top: 7px;
		padding-bottom: 14px;
		font-weight: bold;
		font-size: 12px;
		color: #1a1a1a;
	}
	.ss-ledger tr.ss-sub.last td { padding-bottom: 0; }

	.ss-foot {
		margin-top: 18px;
		padding-top: 10px;
		border-top: 1px solid #e2e2e2;
		font-size: 10px;
		color: #757575;
	}
	.ss-foot strong { color: #444444; font-weight: bold; }
	.ss-foot td { padding-right: 18px; }
	.ss-foot td.ref { padding-right: 0; text-align: right; }
</style>

<div class="ss-doc ss-compact">
	{% if letter_head and not no_letterhead %}
	<div class="letter-head">{{ letter_head }}</div>
	{% endif %}
	<div class="ss-head-rule"></div>

	<table class="ss-who">
		<tr>
			<td>
				<div class="name">{{ doc.employee_name }}</div>
				<div class="sub">
					{%- if doc.designation %}{{ doc.designation }} &bull; {% endif -%}
					{%- if doc.department %}{{ doc.department }} &bull; {% endif -%}
					{{ doc.employee }}
				</div>
			</td>
			<td class="ss-right">
				<div class="ss-label">{{ _("Payslip for") }}</div>
				<div class="period ss-num">
					{{ frappe.format(doc.start_date, {"fieldtype": "Date"}) }}
					{{ _("to") }} {{ frappe.format(doc.end_date, {"fieldtype": "Date"}) }}
				</div>
			</td>
		</tr>
	</table>

	<table class="ss-hero">
		<tr>
			<td>
				<div class="ss-label">{{ _("Net Pay") }}</div>
				<div class="amt ss-num">{{ money(net_total) }}</div>
				<div class="words">{{ doc.total_in_words }}</div>
			</td>
			<td class="pay">
				{%- if doc.bank_name or doc.mode_of_payment %}
				<div class="ss-label">{{ _("Credited to") }}</div>
				{%- if doc.bank_name -%}
					<div>{{ doc.bank_name }}</div>
					{%- if doc.bank_account_no %}<div>{{ _("A/C") }} {{ doc.bank_account_no }}</div>{% endif -%}
				{%- else -%}
					<div>{{ _(doc.mode_of_payment) }}</div>
				{%- endif -%}
				{% endif -%}
			</td>
		</tr>
	</table>

	<table class="ss-ledger">
		<colgroup><col><col class="amt"></colgroup>
		<tbody>
			<tr class="ss-sec first">
				<td class="c">{{ _("Earnings") }}</td>
				<td>{{ _("Amount") }}</td>
			</tr>
			{% for row in earnings %}
			<tr>
				<td class="c">{{ _(row.salary_component) }}</td>
				<td class="ss-num">{{ money(row.amount) }}</td>
			</tr>
			{% endfor %}
			<tr class="ss-sub">
				<td class="c">{{ _("Gross Pay") }}</td>
				<td class="ss-num">{{ money(doc.gross_pay) }}</td>
			</tr>

			<tr class="ss-sec">
				<td class="c">{{ _("Deductions") }}</td>
				<td>{{ _("Amount") }}</td>
			</tr>
			{% for row in deductions %}
			<tr>
				<td class="c">{{ _(row.salary_component) }}</td>
				<td class="ss-num">{{ money(row.amount) }}</td>
			</tr>
			{% endfor %}
			<tr class="ss-sub last">
				<td class="c">{{ _("Total Deduction") }}</td>
				<td class="ss-num">{{ money(doc.total_deduction) }}</td>
			</tr>
		</tbody>
	</table>

	<table class="ss-foot">
		<tr>
			<td><strong>{{ _("Working days") }}</strong> {{ doc.total_working_days }}</td>
			<td><strong>{{ _("Payment days") }}</strong> {{ doc.payment_days }}</td>
			<td><strong>{{ _("Leave without pay") }}</strong> {{ doc.leave_without_pay }}</td>
			<td class="ref">{{ doc.name }}</td>
		</tr>
	</table>
</div>
